  assert.equal(r1.ok, true);
  assert.equal(r2.ok, true);
  assert.equal(typeof r1.value, 'number');
  assert.equal(typeof r2.value, 'number');
});

test('formatMoney formats USD with $ symbol', () => {
  const r = convert(123456, 'USD');
  const formatted = formatMoney(r.value, 'USD');

  assert(formatted.includes('$'));
  assert(formatted.includes(','));
  assert(formatted.includes('.'));
});

test('formatMoney formats GBP with £ symbol', () => {
  const r = convert(123456, 'GBP');
  const formatted = formatMoney(r.value, 'GBP');

  assert(formatted.includes('£'));
});

test('formatMoney formats EUR with € symbol', () => {
  const formatted = formatMoney(123456, 'EUR');

  assert(formatted.includes('€'));
});

test('formatMoney handles negative amounts with sign', () => {
  const formatted = formatMoney(-5000, 'USD');

  assert(formatted.includes('-'));
  assert(formatted.startsWith('-'));
});

test('formatMoney formats decimals correctly', () => {
  const formatted = formatMoney(5, 'USD');

  assert.equal(formatted, '$0.05');
});

test('formatMoney adds thousands separators', () => {
  const formatted = formatMoney(1000000, 'USD');

  assert(formatted.includes(','));
  assert.equal(formatted, '$10,000.00');
});

test('formatMoney with zero amount', () => {
  const formatted = formatMoney(0, 'USD');

  assert.equal(formatted, '$0.00');
});

test('convert and formatMoney work together', () => {
  const eurocents = 95000;
  const convertResult = convert(eurocents, 'USD');
  assert.equal(convertResult.ok, true);

  const formatted = formatMoney(convertResult.value, 'USD');

  assert(formatted.includes('$'));
  assert(formatted.includes('.'));
  const parts = formatted.split('.');
  assert.equal(parts[1].length, 2);
});

test('convert preserves cents precision', () => {
  const r = convert(123, 'USD');

  assert.equal(r.ok, true);
  assert.equal(r.value, Math.round(123 * 1.085));
});

test('formatMoney pads cents to 2 digits', () => {
  const formatted1 = formatMoney(1005, 'USD');
  const formatted2 = formatMoney(1050, 'USD');

  assert(formatted1.includes('.05'));
  assert(formatted2.includes('.50'));
});

test('convert works with different rates', () => {
  const usdCents = 108500;
  const gbpCents = 84250;

  const usd = convert(usdCents, 'USD');
  const gbp = convert(gbpCents, 'GBP');

  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);
  assert(usd.value > gbp.value);
});
